def xargs(cmd, varargs, color=False, target_concurrency=1, max_length=None, **kwargs):
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    if not cmd:
        raise ValueError("cmd cannot be empty")

    if max_length is None:
        max_length = _get_platform_max_length()

    arg_batches = _get_arg_batches(varargs, target_concurrency, max_length)
    results = []
    with Pool(target_concurrency) as pool:
        for batch in arg_batches:
            result = pool.apply_async(_run_cmd, (cmd, batch, color, **kwargs))
            results.append(result)

    return tuple(result.get() for result in results)

