def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(func):
        if isinstance(func, (classmethod, MethodType)):
            instance = func.__self__

            @wraps(func)
            def wrapper(*args, **kwargs):
                if lock:
                    lock.acquire()
                try:
                    # Check if the result is already cached
                    result = cache.get(key(*args, **kwargs))
                    if result is None:
                        # If not, call the original method and store the result in the cache
                        result = func(*args, **kwargs)
                        cache[key(*args, **kwargs)] = result
                finally:
                    if lock:
                        lock.release()
                return result

            return wrapper
        else:
            raise ValueError("cachedmethod decorator can only be applied to methods, not functions")

    return decorator

