def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest:
        if resource.metadata.namespace is None:
            resource.metadata.namespace = app.metadata.namespace
        if resource.metadata.labels is None:
            resource.metadata.labels = app.metadata.labels
        if resource.metadata.annotations is None:
            resource.metadata.annotations = app.metadata.annotations

        if not hasattr(resource, "spec"):
            resource.spec = {}

        if not hasattr(resource, "status"):
            resource.status = {"observed_generation": None}

        resource.status.observed_generation = app.metadata.generation

