        raise Invalid(f"{candidate!r} does not provide {iface!r}")

    errors = []

    # Check that all methods are defined
    for method_name, method in iface.methods.items():
        if not hasattr(candidate, method_name):
            errors.append(Invalid(f"{candidate!r} does not define method {method_name!r}"))
            continue

        # Check method signature (to the extent possible)
        method_sig = inspect.signature(method)
        candidate_sig = inspect.signature(getattr(candidate, method_name))
        if not candidate_sig.parameters == method_sig.parameters:
            errors.append(Invalid(f"{candidate!r} defines method {method_name!r} with wrong signature"))

    # Check that all attributes are defined
    for attr_name in iface.attributes:
        if not hasattr(candidate, attr_name):
            errors.append(Invalid(f"{candidate!r} does not define attribute {attr_name!r}"))

    # Raise any remaining errors
    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            raise Invalid(errors)

    return True

