def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If explicit metaclass is not None, use it
    if explicit_mc is not None:
        return explicit_mc

    # Otherwise, determine the metaclass based on the bases
    mcs = [base.__class__ for base in bases]
    if not mcs:
        return type

    # Check for special cases
    if type in mcs:
        return type

    # Find the lowest class in the hierarchy
    mc = mcs[0]
    for cls in mcs[1:]:
        if issubclass(mc, cls):
            mc = cls

    return mc

