    """Test a word whether it could be accepted as a tag."""

    if not isinstance(tag, str) or len(tag) == 0:
        return False

    if tag[0] not in 'abcdefghijklmnopqrstuvwxyz' or tag[-1] not in 'abcdefghijklmnopqrstuvwxyz':
        return False

    for char in tag:
        if char not in 'abcdefghijklmnopqrstuvwxyz0123456789':
            return False

    return True

